insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('JP:truck-driver','2026-08-11',0,0,0,0,15,0,0,0,2,17,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Truck Driver spans MHLW 083-01 large truck, 083-02 medium/small truck, 083-03 tractor-trailer, 083-04 dump truck and 083-99 other freight-truck driving rather than one exact small classification.','entry_level_basis','This is primarily a vehicle-licence and employer-training pathway rather than an academic occupation.','qualification_note','Driving requires the licence class appropriate to the vehicle. Higher truck classes and articulated vehicles can require staged licence experience and a separate towing licence.','market_scope','The freight-truck classes are preserved separately and are not merged into one fabricated exact market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('JP:logistics-coordinator','2026-08-11',0,0,0,0,15,0,0,0,5,20,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Logistics Coordinator spans 039-02 shipping/receiving and warehouse administration plus 042-02 transport-operation dispatch/coordination where vehicle scheduling is central.','entry_level_basis','Operations, logistics or supply-chain study can help, but many roles are entered through shipping, warehouse or transport-office experience; the one reviewed Japanese programme is related.','qualification_note','No universal statutory Logistics Coordinator licence applies. Regulated transport-operation-manager duties are narrower than the canonical role and are not promoted into a blanket requirement.','market_scope','Administrative shipping/receiving and transport dispatch classifications are not merged into an exact logistics-coordinator market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('JP:aircraft-maintenance-technician','2026-08-11',0,0,0,0,10,0,0,0,1,11,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','MHLW 075-04 includes aircraft maintenance and repair work within transport-equipment maintenance excluding automobiles.','entry_level_basis','Aviation-maintenance vocational or technical study plus practical experience is the common route; one approved Japanese aircraft-maintenance programme is direct.','qualification_note','MHLW job tag states that the national aircraft-maintenance qualification under the Civil Aeronautics Act is required for the 航空整備士 occupation, with licence class and aircraft-category limitations.','market_scope','075-04 also covers other non-automotive transport equipment, so its group statistics are not treated as exact aircraft-maintenance observations.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('JP:commercial-pilot','2026-08-11',0,0,0,0,8,0,0,0,1,9,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','MHLW 087-04 directly classifies aircraft pilots and includes airline and other professional aircraft-operation scopes.','entry_level_basis','Commercial flying requires structured flight training, aeronautical experience, examinations, flight testing and medical fitness; there are currently no approved Japan programme links in the reviewed programme staging for this canonical career.','qualification_note','Paid commercial aircraft operation requires the applicable MLIT aviation personnel skill certificate; airline command requires the higher airline transport pilot qualification and pilots also face medical-certificate requirements.','market_scope','Pilot market evidence is deferred even though current official sources publish occupation information, to keep scoring comparable with the later cross-country enrichment phase.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('JP:marine-engineer','2026-08-11',0,0,0,0,8,0,0,0,1,9,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','MHLW 087-03 directly covers ship chief engineers and engineer officers on non-fishing vessels.','entry_level_basis','Maritime engineering education, approved training and documented sea service lead toward engineer-officer work; the reviewed Osaka maritime programme is retained as related rather than automatic licence qualification.','qualification_note','Serving as a ship engineer officer requires the applicable 海技士（機関） certificate under Japan maritime qualification law, with class and vessel-duty limits.','market_scope','No market score is assigned in this foundation phase despite available maritime-industry context.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('JP:deck-officer','2026-08-11',0,0,0,0,8,0,0,0,1,9,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','MHLW 087-02 directly covers masters, deck/navigation officers and operations officers on non-fishing vessels, plus pilots; CampCareer restricts this canonical profile to deck/navigation officer scope.','entry_level_basis','Nautical education, approved training and documented sea service are standard foundations for deck-officer qualification; no reviewed Japan programme link is currently approved for this canonical career.','qualification_note','Serving as a deck/navigation officer requires the applicable 海技士（航海） certificate under Japan maritime qualification law, with grade and vessel-duty limits.','market_scope','The official classification also contains masters and maritime pilots, so group-level data are not treated as exact Deck Officer observations.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('JP:warehouse-manager','2026-08-11',0,0,0,0,10,0,0,0,5,15,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Warehouse Manager has no single MHLW small code: higher organisational management can fall under 002-01, warehouse administration and inventory control under 039-02, and hands-on warehouse operations under 095-03.','entry_level_basis','Warehouse management is commonly reached through logistics or warehouse operations experience plus supervisory responsibility; the one reviewed Japanese programme is related.','qualification_note','No universal personal Warehouse Manager licence applies. 倉庫管理主任者 and other designated credentials can apply to particular warehousing businesses or responsibilities without licensing the entire occupation.','market_scope','Management, warehouse administration and physical warehouse work are not aggregated into one fabricated exact market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('JP:automotive-service-technician','2026-08-11',0,0,0,0,12,0,0,0,4,16,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','MHLW 075-03 directly covers automotive inspection, servicing and repair work including mechanics and automotive electrical repair.','entry_level_basis','Automotive vocational study is common, but MHLW job tag explicitly notes that employment at a repair workshop is possible before obtaining the national automotive-mechanic qualification; three reviewed university automotive programmes are related rather than trade-qualification pathways.','qualification_note','The national 自動車整備士 qualification is valuable and required for specified higher-responsibility work, but it is not a universal personal licence required merely to enter every automotive service technician job.','market_scope','075-03 is a strong occupational match, but market and salary components remain deferred for consistency with the common enrichment phase.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11')
